snippet.code:
pipeline {
  agent { label 'academy-test' }
  options { timeout(time: 10, unit: 'MINUTES') }
  stages {
    stage('Test') {
      steps { sh 'python -m unittest discover' }
    }
  }
  post {
    always { echo 'Test attempt finished' }
  }
}

variable "replicas" {
  type    = number
  default = 2
  validation {
    condition     = var.replicas >= 1 && var.replicas <= 5 && floor(var.replicas) == var.replicas
    error_message = "Use an integer from 1 to 5."
  }
}
locals {
  service_name = "academy-demo"
}
output "name" {
  value = local.service_name
}

resource "terraform_data" "service" {
  for_each = toset(["api", "worker"])
  input    = each.key
}

resource "terraform_data" "config" {
  input = "v1"
}
resource "terraform_data" "consumer" {
  input = terraform_data.config.output
}

moved {
  from = terraform_data.app
  to   = terraform_data.service
}
resource "terraform_data" "service" {
  input = "v1"
}

run "default_replicas" {
  command = plan
  assert {
    condition     = var.replicas == 2
    error_message = "Expected default of two replicas."
  }
}

terraform {
  required_version = ">= 1.6, < 2.0"
  backend "local" {
    path = "terraform.tfstate"
  }
}

